TLM.f("Tempora/Quadp1-5",{"officium":"Feria VI infra Hebdomadam Septuagesimæ","rule":["vide Quadp1-0","no Gloria","Suffragium=Maria2;Papa,Ecclesiæ;;"],"ruleInherited":["no Gloria","Credo","Prefatio=Trinitate","Suffr=Maria2;Sanctorum,Ecclesiæ;;"],"fallback":"Tempora/Quadp1-0","from":{"Introitus":"Tempora/Quadp1-0","Oratio":"Tempora/Quadp1-0","Lectio":"Tempora/Quadp1-0","Graduale":"Tempora/Quadp1-0","GradualeF":"Tempora/Quadp1-0","Evangelium":"Tempora/Quadp1-0","Offertorium":"Tempora/Quadp1-0","Secreta":"Tempora/Quadp1-0","Communio":"Tempora/Quadp1-0","Postcommunio":"Tempora/Quadp1-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 17:5; 17:6; 17:7"},{"k":"text","la":"Circumdedérunt me gémitus mortis, dolóres inférni circumdedérunt me: et in tribulatióne mea invocávi Dóminum, et exaudívit de templo sancto suo vocem meam."},{"k":"ref","la":"Ps 17:2-3"},{"k":"text","la":"Díligam te, Dómine, fortitúdo mea: Dóminus firmaméntum meum, et refúgium meum, et liberátor meus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Circumdedérunt me gémitus mortis, dolóres inférni circumdedérunt me: et in tribulatióne mea invocávi Dóminum, et exaudívit de templo sancto suo vocem meam."}],"Oratio":[{"k":"text","la":"Preces pópuli tui, quǽsumus, Dómine, cleménter exáudi: ut, qui juste pro peccátis nostris afflígimur, pro tui nóminis glória misericórditer liberémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"1 Cor 9:24-27; 10:1-5"},{"k":"text","la":"Fratres: Nescítis, quod ii, qui in stádio currunt, omnes quidem currunt, sed unus áccipit bravíum? Sic cúrrite, ut comprehendátis. Omnis autem, qui in agóne conténdit, ab ómnibus se ábstinet: et illi quidem, ut corruptíbilem corónam accípiant; nos autem incorrúptam. Ego ígitur sic curro, non quasi in incértum: sic pugno, non quasi áërem vérberans: sed castígo corpus meum, et in servitútem rédigo: ne forte, cum áliis prædicáverim, ipse réprobus effíciar. Nolo enim vos ignoráre, fratres, quóniam patres nostri omnes sub nube fuérunt, et omnes mare transiérunt, et omnes in Móyse baptizáti sunt in nube et in mari: et omnes eándem escam spiritálem manducavérunt, et omnes eúndem potum spiritálem bibérunt bibébant autem de spiritáli, consequénte eos, petra: petra autem erat Christus: sed non in plúribus eórum beneplácitum est Deo."}],"Graduale":[{"k":"ref","la":"Ps 9:10-11; 9:19-20"},{"k":"text","la":"Adjútor in opportunitátibus, in tribulatióne: sperent in te, qui novérunt te: quóniam non derelínquis quæréntes te, Dómine,"},{"k":"text","la":"Quóniam non in finem oblívio erit páuperis: patiéntia páuperum non períbit in ætérnum: exsúrge, Dómine, non præváleat homo.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 129:1-4"},{"k":"text","la":"De profúndis clamávi ad te. Dómine: Dómine, exáudi vocem meam."},{"k":"text","la":"Fiant aures tuæ intendéntes in oratiónem servi tui.","mark":"V"},{"k":"text","la":"Si iniquitátes observáveris, Dómine: Dómine, quis sustinébit?","mark":"V"},{"k":"text","la":"Quia apud te propitiátio est, et propter legem tuam sustínui te, Dómine.","mark":"V"}],"GradualeF":[{"k":"ref","la":"Ps 9:10-11; 9:19-20"},{"k":"text","la":"Adjútor in opportunitátibus, in tribulatióne: sperent in te, qui novérunt te: quóniam non derelínquis quæréntes te, Dómine,"},{"k":"text","la":"Quóniam non in finem oblívio erit páuperis: patiéntia páuperum non períbit in ætérnum: exsúrge, Dómine, non præváleat homo.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 20:1-16"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Simile est regnum coelórum hómini patrifamílias, qui éxiit primo mane condúcere operários in víneam suam. Conventióne autem facta cum operáriis ex denário diúrno, misit eos in víneam suam. Et egréssus circa horam tértiam, vidit álios stantes in foro otiósos, et dixit illis: Ite et vos in víneam meam, et quod justum fúerit, dabo vobis. Illi autem abiérunt. Iterum autem éxiit circa sextam et nonam horam: et fecit simíliter. Circa undécimam vero éxiit, et invénit álios stantes, et dicit illis: Quid hic statis tota die otiósi? Dicunt ei: Quia nemo nos condúxit. Dicit illis: Ite et vos in víneam meam. Cum sero autem factum esset, dicit dóminus víneæ procuratóri suo: Voca operários, et redde illis mercédem, incípiens a novíssimis usque ad primos. Cum veníssent ergo qui circa undécimam horam vénerant, accepérunt síngulos denários. Veniéntes autem et primi, arbitráti sunt, quod plus essent acceptúri: accepérunt autem et ipsi síngulos denários. Et accipiéntes murmurábant advérsus patremfamílias, dicéntes: Hi novíssimi una hora fecérunt et pares illos nobis fecísti, qui portávimus pondus diéi et æstus. At ille respóndens uni eórum, dixit: Amíce, non facio tibi injúriam: nonne ex denário convenísti mecum? Tolle quod tuum est, et vade: volo autem et huic novíssimo dare sicut et tibi. Aut non licet mihi, quod volo, fácere? an óculus tuus nequam est, quia ego bonus sum? Sic erunt novíssimi primi, et primi novíssimi. Multi enim sunt vocáti, pauci vero elécti."}],"Offertorium":[{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino, et psállere nómini tuo, Altíssime."}],"Secreta":[{"k":"text","la":"Munéribus nostris, quǽsumus, Dómine, precibúsque suscéptis: et cœléstibus nos munda mystériis, et cleménter exáudi."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 30:17-18"},{"k":"text","la":"Illúmina fáciem tuam super servum tuum, et salvum me fac in tua misericórdia: Dómine, non confúndar, quóniam invocávi te."}],"Postcommunio":[{"k":"text","la":"Fidéles tui, Deus, per tua dona firméntur: ut eadem et percipiéndo requírant, et quæréndo sine fine percípiant."},{"k":"macro","name":"Per Dominum"}]},"hr":{"e8e481709a6ba546":{"t":"Ps 17, 5 i 6 i 7, Ps 17, 2-3\n(Ps 17, 5 i 6 i 7) Obuzeše me vapaji smrtni, spopadoše me paklene Boli. U nevolji svojoj zazvah Gospodina i usliši moj glas iz svetog hrama svojega. (Ps 17, 2-3). Ljubit ću te, Gospodine, jakosti moja. Gospodin je moja tvrđava, moje utočište i moj osloboditelj.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\nObuzeše me vapaji smrtni, spopadoše me paklene Boli. U nevolji svojoj zazvah Gospodina i usliši moj glas iz svetog hrama svojega.","kn":"(Ps. 17, 7). Uslišao je iz hrama svoga svetoga glas moj, aleluja; i vapaj je moj dopro do uha nj«- gova, aleluja, aleluja. (Ps. 17, 2) Ljubim Te, Gospodine, kreposti moja; Gospodin je tvrđava moja i utočište moje i izbavitelj moj. Slava Ocu . . . Uslišao je . . .","knRef":"Kniewald 1942, str. 328–329 (snimka 165) (OCR)"},"3a495bdd3f7e4789":{"t":"<i>Pomolimo se</i>.\nMolitve puka Svojega, molimo, Gospodine, milostivo usliši da mi koji s pravom trpimo zbog svojih grijeha, milosrdno budemo spašeni na slavu tvojeg imena.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo. Te, Gospodine, usliši milostivo molitve puka svoga, da mi, .koji pravedno trpimo radi svojih grijeha, milosrdno budemo izbavljeni radi .slave imena. .Tvoga, . po, G, n. . I. K.. . .","knRef":"Kniewald 1942, str. 88–89 (snimka 45) (OCR)"},"7fbe746c3f30ef79":{"t":"1 Kor 9, 24-27 i 10, 1-5\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo: zar ne znate da u trkalištu svi trkači trče, ali samo jedan dobiva nagradu. Trčite tako da je vi odnesete! Svi se natjecatelji uzdržavaju od svega: oni da dobiju raspadljivi vijenac, a mi neraspadljivi. Ja stoga tako trčim, ne kao da nemam cilja; tako dajem udarce, ne kao onaj koji mlati vjetar. Naprotiv, krotim svoje tijelo i činim ga podložnim da ne bih možda, dok drugima propovijedam, sam bio odbačen. – Htio bih da znate, braćo, da su svi naši oci bili pod oblakom; da su svi prešli preko mora; da su svi po Mojsiju kršteni u oblaku i u moru; da su svi jeli isto duhovno jelo i pili isto duhovno piće. Pili su naime od duhovne stijene što ih je pratila, a ta je stijena bio Krist. Ipak mnogi od njih nisu bili Bogu po volji.","kn":"- Citarij© poslalilce -bi. Pavla apostola Korinćaniitta (T, - 9; 24-27. 10,s 1-5). Brać-o! Zar rife mate,' da . oni, koji 'trče utrkalištu-, zaistd'isvt teče, i ali 'jedari dobiva nagradu. Tako trčite, da đostignete. A kojigod se bori, uzdržava se did svega;, oni, da dobiju raspadljiv vijenac, a mi neraspadljiv. A, ja tako trčim, ne kao bez cilja, tako - se , Jodrim, ne kao onaj, k,o.ji mlati vjetar, nego obuzdavam svoje tijelo i do-go- INedjelja sedamdesetnica nim u pokoroost, da, dok drugima propovijedam, ne bih možda sam bio osuđen. Jer ne ću vam, broićo, tajiti, kako su naši oci bili evi pod oblakom, i svi su prešli preko mora, i svi su bili krštenl ipo Mojsiji u oblaku i u moru; svi su jeli isto duihovno jelo, i svi pili isto duhovno Plće (Pili su naime od duhovne stijene, koja ih je pratila, a ta stijena bio je Krist). Ali se većina od njih nije svidjela Bogu.","knRef":"Kniewald 1942, str. 88–89 (snimka 45) (OCR)"},"4e4bf3c0ebb0c275":{"t":"Ps 9, 10-11 i 19-20\nU pravo vrijeme ti si pomoćnik u nevolji. Koji te poznaju uzdaju se u te, jer ne zapuštaš onih koji te traže, Gospodine. Neće siromah biti zaboravljen, strpljivost ubogih neće propasti zauvijek. Ustani, Gospodine, da se ne osili čovjek.","kn":"(Ps. 9, 10, 11, 19, 20). Ti si pomoćnik u nevolji, u pravo vrijeme, neka se, dakle, uzdaju u Te svi, koji Te znadu, jer nikad ne ostavljaš onih, koji Te traže. Gospodine! Jer ne će do 'vijeka ostati u zaboravi bijednik, nada ubogih ne će biti zauvijek prevarena; ustani. Gospodine, da se čovjek ne ponese!","knRef":"Kniewald 1942, str. 90–91 (snimka 46) (OCR)"},"69596196e6f7a74a":{"t":"Mt 20, 1-16\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: reče Isus svojim učenicima ovu usporedbu: Nebesko je kraljevstvo slično domaćinu koji izađe rano ujutro da najmi radnike za svoj vinograd. Kad se s radnicima pogodio po dinar na dan, posla ih u svoj vinograd. Iziđe i oko trećeg sata i vidi druge gdje besposleni stoje na trgu i reče im: »Idite i vi u moj vinograd i dat ću vam što bude pravo.« Pođu i oni. Ponovo iziđe oko šestog i devetog sata i učini isto tako. Iziđe i oko jedanaestoga sata i nađe druge gdje stoje te ih upita: »Zašto stojite ovdje čitav dan bez posla?« Oni odgovore: »Nitko nas nije unajmio.« Reče i njima: »Pođite i vi u moj vinograd!« Navečer gospodar vinograda reče svome upravitelju: »Dozovi radnike i daj im plaću od posljednjih do prvih.« Tako pristupe oni od jedanaestog sata i prime po dinar. Kad su došli na red prvi, mislili su da će dobiti više, ali i oni dobiju po dinar. Kad su primili, počnu mrmljati protiv domaćina prigovarajući: »Ovi su posljednji radili samo jedan sat, a ti si ih izjednačio s nama koji smo podnijeli tegobu dana i žegu.« A on odgovori jednomu od njih: »Prijatelju, ne činim ti krivo. Zar se nisi pogodio sa mnom po dinar? Uzmi svoje i pođi, a ja hoću i ovom posljednjem dati kao i tebi. Zar mi nije slobodno s mojim činiti što hoću? Ili je tvoje oko zavidno, što sam ja dobar?« Tako će posljednji biti prvi, a prvi posljednji; jer je mnogo zvanih, a malo odabranih.","kn":"t Slijedi sveto evanđelje po Mateju (20, 1-16). U ono vrijeme reče Isus svojim učenicima ovu prispodobu; Nebesko je kraljevstvo kao domaćin, koji iziđe rano ujutro, da najmi radnike za svoj vinograd. Iziđe i oko treće ure^ i vidi druge, gdje stoje na trgu bez posla i reče im: Idite i vi u moj vinograd, i što bude pravo, dat ću vam. I oni pođu. Opet iziđe oko šeste i devete ure^ i učini tako. Kad je izišao , oko jedanaeste,^ nađe druge, gdje stoje, i upita ih: Sto stojite ovdje cijeli dan bez posla? Oni mu odgovoriše: Jer nas nije nitko najmio. Reče im: Idite i vi u moj vinograd. A kad bi navečer, reče gospodar vinograda svomu upravitelju: Dozovi radnike i isplati im počevši od posljednjih do prvih. Kad su došli oni, koji su ušli oko jedanaeste ure, primiše po dinar. A kad su došli i prvi, mislili su, da će dobiti više. Ali i oni primiše po dinar. A kad su primili, stanu mrmljati protiv domaćina' govoreći: Ovi posljednji radili su jednu uru i izjednačio si ih s nama, koji smo podnosili teret dana i žegu. A on odgovori jednomu od njih: Prijatelju, ne činim ti krivo. Zar se nijesi sa mnom pogodio, po dinar? Uzmi svoje, pa idi, jer hoću i ovomu posljednjemu dati kao i tebi. Ili zar da ja ne radim, što hoću? Zar si ti zavidan, što sam ja dobar? Tako će posljednji biti prvi, a prvi posljednji; jer je mnogo zvanih, a malo izabranih.","knRef":"Kniewald 1942, str. 90–91 (snimka 46) (OCR)"},"fc9a3326ffdc2b0b":{"t":"Ps 91, 2\nDobro je slaviti Gospodina i pjevati tvojem imenu, Svevišnji.","kn":"(Ps. 91, 2). Dobro je slaviti Gospodina i pjevati imenu Tvojemu, Višnji.","knRef":"Kniewald 1942, str. 90–91 (snimka 46) (OCR)"},"0741f87b36183013":{"t":"Primi, molimo, Gospodine, naše darove i molitve te nas nebeskim otajstvima očisti i milostivo usliši.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, naše darove i molitve, te nas blago usliši i očisti nebeskim otajstvima, Po . G. n.","knRef":"Kniewald 1942, str. 572–573 (snimka 287) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"316518ee9dc3b674":{"t":"Ps 30, 17-18\nNeka sine tvoje lice nad slugom tvojim i spasi me svojim milosrđem. Ne daj, Gospodine, da budem postiđen kad sam zazvao tebe.","kn":"(Ps. 30, 17, 18). Po'kaži svijetlo lice svoje sluzi svO'jemu, spasi me po milosrđu svojem. Gospodine, ne daj, da budem postiđen, jer Tebe prizivi] em!","knRef":"Kniewald 1942, str. 90–91 (snimka 46) (OCR)"},"b37f7e3a173da092":{"t":"<i>Pomolimo se</i>.\nVjernici tvoji, Bože, neka se tvojim darovima učvrste, da ih primajući traže i tražeći ih uvijek primaju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Bože, da se Tvoji vjennici ovim darovima učvrste, te da ih i primajući traže i tražeći bez prestanka primaju, po G. n. I. K.","knRef":"Kniewald 1942, str. 90–91 (snimka 46) (OCR)"}}});
